function nearestPeriod(periods: EraSummary[], year: number): EraSummary {
  let best = periods[0];
  let bestDist = Infinity;
  for (const p of periods) {
    const dist = year < p.from ? p.from - year : year > p.to ? year - p.to : 0;
    if (dist < bestDist) {
      bestDist = dist;
      best = p;
    }
  }
  return best;
}

// Returns the era-appropriate summary for a territory at a given year,
// or null if the territory has no curated summary. `name` must be the
// original GeoJSON NAME/SUBJECTO (not the translated display name).
export function summaryFor(name: string, year: number): string | null {
  const periods = TERRITORY_SUMMARIES[name];
  if (!periods || periods.length === 0) return null;
  const containing = periods.find((p) => year >= p.from && year <= p.to);
  return (containing ?? nearestPeriod(periods, year)).text;
}
